from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover an h×w grid."""
    if n != len(tiles) or h <= 0 or w <= 0:
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]
    shapes = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        shapes.append(tuple(orientations))

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True

        empty = full ^ occupied
        needed = empty.bit_count()
        # Some subset of the remaining tiles must have exactly the area left.
        sums = {0}
        for i, area in enumerate(areas):
            if available & (1 << i):
                sums |= {s + area for s in tuple(sums) if s + area <= needed}
        if needed not in sums:
            return False

        # The first empty cell determines an anchor for the next rectangle.
        first = (empty & -empty).bit_length() - 1
        row, col = divmod(first, w)

        for i in range(n):
            bit = 1 << i
            if not (available & bit):
                continue
            for height, width in shapes[i]:
                if row + height > h or col + width > w:
                    continue
                placement = 0
                row_bits = ((1 << width) - 1) << (row * w + col)
                for rr in range(row, row + height):
                    placement |= row_bits + (((1 << width) - 1) << (rr * w + col)) - row_bits if False else ((1 << width) - 1) << (rr * w + col)
                if occupied & placement == 0 and search(occupied | placement, available ^ bit):
                    return True
        return False

    # Areas larger than the board can never be used.
    possible = 0
    for i, area in enumerate(areas):
        if area <= h * w:
            possible |= 1 << i
    return search(0, possible)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple paths of K moves starting from any empty cell."""
    open_cells = [
        r * W + c
        for r in range(H)
        for c in range(W)
        if grid[r][c] == "."
    ]
    if K >= len(open_cells):
        return 0

    neighbors = [[] for _ in range(H * W)]
    for r in range(H):
        for c in range(W):
            cell = r * W + c
            if r > 0:
                neighbors[cell].append(cell - W)
            if r + 1 < H:
                neighbors[cell].append(cell + W)
            if c > 0:
                neighbors[cell].append(cell - 1)
            if c + 1 < W:
                neighbors[cell].append(cell + 1)

    usable = set(open_cells)
    answer = 0

    def visit(cell: int, steps_left: int, seen: set[int]) -> None:
        nonlocal answer
        if steps_left == 0:
            answer += 1
            return
        for nxt in neighbors[cell]:
            if nxt in usable and nxt not in seen:
                seen.add(nxt)
                visit(nxt, steps_left - 1, seen)
                seen.remove(nxt)

    for start in open_cells:
        visit(start, K, {start})
    return answer

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover an h×w grid."""
    if n != len(tiles) or h <= 0 or w <= 0:
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]
    shapes = [tuple({(a, b), (b, a)}) for a, b in tiles]

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True

        empty = full ^ occupied
        needed = empty.bit_count()
        sums = {0}
        for i, area in enumerate(areas):
            if available & (1 << i):
                sums |= {s + area for s in tuple(sums) if s + area <= needed}
        if needed not in sums:
            return False

        first = (empty & -empty).bit_length() - 1
        row, col = divmod(first, w)

        for i in range(n):
            bit = 1 << i
            if not (available & bit):
                continue
            for height, width in shapes[i]:
                if row + height > h or col + width > w:
                    continue
                row_mask = ((1 << width) - 1) << col
                placement = 0
                for rr in range(row, row + height):
                    placement |= row_mask << (rr * w)
                if occupied & placement == 0 and search(occupied | placement, available ^ bit):
                    return True
        return False

    available = sum(1 << i for i, area in enumerate(areas) if area <= h * w)
    return search(0, available)

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = tuple(map(int, str(n)))

        @lru_cache(maxsize=None)
        def visit(pos: int, digit_sum: int, digit_product: int, tight: bool) -> int:
            if pos == len(digits):
                return int(digit_sum > 0 and digit_product % digit_sum == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                total += visit(
                    pos + 1,
                    digit_sum + digit,
                    digit_product * digit,
                    tight and digit == limit,
                )
            return total

        # Count each shorter length separately so leading zeroes are never
        # treated as digits of the number.
        total = 0
        for length in range(1, len(digits)):
            short_digits = (9,) * length

            @lru_cache(maxsize=None)
            def visit_short(pos: int, digit_sum: int, digit_product: int) -> int:
                if pos == length:
                    return int(digit_sum > 0 and digit_product % digit_sum == 0)
                lo = 1 if pos == 0 else 0
                result = 0
                for digit in range(lo, 10):
                    result += visit_short(
                        pos + 1, digit_sum + digit, digit_product * digit
                    )
                return result

            total += visit_short(0, 0, 1)

        # For the length of n, the first digit must be nonzero. The digit DP
        # includes a tight flag to enforce the upper bound.
        @lru_cache(maxsize=None)
        def visit_fixed(pos: int, digit_sum: int, digit_product: int, tight: bool) -> int:
            if pos == len(digits):
                return int(digit_sum > 0 and digit_product % digit_sum == 0)
            limit = digits[pos] if tight else 9
            lo = 1 if pos == 0 else 0
            result = 0
            for digit in range(lo, limit + 1):
                result += visit_fixed(
                    pos + 1,
                    digit_sum + digit,
                    digit_product * digit,
                    tight and digit == limit,
                )
            return result

        total += visit_fixed(0, 0, 1, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

