def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper pattern."""
    # Every unit square is either monochrome, or bisected by a diagonal.
    # In square (i, j), a diagonal crosses the interior exactly when i+j is odd.
    # Such a square contributes 1 to twice the black area. For the other squares,
    # parity of the region containing an interior point determines whether it is black.
    weights = []
    for j in range(4):
        row = []
        for i in range(4):
            if (i + j) & 1:
                row.append(1)
            else:
                parity = (i + (j // 2) + ((i + j) // 2)) & 1
                row.append(0 if parity else 2)
        weights.append(row)

    tile_total = sum(map(sum, weights))
    row_prefix = [sum(weights[j]) for j in range(4)]
    col_prefix = [sum(weights[j][i] for j in range(4)) for i in range(4)]
    tile_prefix = [[0] * 5 for _ in range(5)]
    for y in range(4):
        for x in range(4):
            tile_prefix[y + 1][x + 1] = (
                weights[y][x] + tile_prefix[y][x + 1]
                + tile_prefix[y + 1][x] - tile_prefix[y][x]
            )

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        return (
            qx * qy * tile_total
            + qx * sum(row_prefix[:ry])
            + qy * sum(col_prefix[:rx])
            + tile_prefix[ry][rx]
        )

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

