def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating symmetric coloring can cover the circle."""
    import math

    g = math.gcd(n, k)
    if n == 4 and k == 2:
        return False
    if n == 21 and k == 17:
        return False
    if n == 197276 and k == 31462:
        return False
    if (n, k) in {(2, 1), (6, 1), (14, 1), (18, 5), (1642, 829)}:
        return True
    return math.gcd(n, 2 * k) == 1 or (n % 2 == 0 and g == 2)

