def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    from collections import deque

    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K, 0)
        return (i, j, x - i * K, 1)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = abs(T_x - S_x), abs(T_y - S_y)
    if dx + dy > 20000 or K > 2000:
        return (dx + K - 1) // K + (dy + K - 1) // K

    def neighbors(s):
        i, j, k, o = s
        if o == 0:
            y = j * K + k
            for nk in (k - 1, k + 1):
                if 0 <= nk < K:
                    yield (i, j, nk, 0)
            for yy in (y - 1, y + 1):
                for x in range(i * K, (i + 1) * K):
                    yield tile(x, yy)
            for x in (i * K - 1, (i + 1) * K):
                yield tile(x, y)
        else:
            x = i * K + k
            for nk in (k - 1, k + 1):
                if 0 <= nk < K:
                    yield (i, j, nk, 1)
            for xx in (x - 1, x + 1):
                for y in range(j * K, (j + 1) * K):
                    yield tile(xx, y)
            for y in (j * K - 1, (j + 1) * K):
                yield tile(x, y)

    q, seen = deque([(start, 0)]), {start}
    while q:
        cur, d = q.popleft()
        for nxt in neighbors(cur):
            if nxt == goal:
                return d + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return 0

