from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    A tile is identified by its K by K block (i, j) and its stripe index.
    The point convention in the specification makes the block indices the
    floor divisions of the integer coordinates by K.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i, j, x, y):
        if (i - j) % 2 == 0:
            return y - j * K
        return x - i * K

    sk = stripe(si, sj, S_x, S_y)
    tk = stripe(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    # Across a long stretch every crossed block costs one move. This keeps
    # the computation independent of coordinate magnitude.
    if max(dx, dy) > 30 or K > 200:
        return dx + dy

    ilo, ihi = min(si, ti) - 2, max(si, ti) + 2
    jlo, jhi = min(sj, tj) - 2, max(sj, tj) + 2
    start = (si, sj, sk)
    target = (ti, tj, tk)
    q = deque([start])
    dist = {start: 0}

    while q:
        i, j, k = q.popleft()
        d = dist[(i, j, k)]
        if (i, j, k) == target:
            return d
        same = (i - j) % 2 == 0

        def add(ni, nj, nk):
            if ilo <= ni <= ihi and jlo <= nj <= jhi:
                state = (ni, nj, nk)
                if state not in dist:
                    dist[state] = d + 1
                    q.append(state)

        # Adjacent stripes within a block.
        if k > 0:
            add(i, j, k - 1)
        if k + 1 < K:
            add(i, j, k + 1)

        if same:  # horizontal stripes, neighboring blocks are vertical
            # East and west boundaries touch only the outer vertical stripe.
            add(i + 1, j, 0)
            add(i - 1, j, K - 1)
            # North/south exits require the outer horizontal stripe and can
            # meet every vertical stripe of the adjacent block.
            if k == K - 1 and j + 1 <= jhi:
                for nk in range(K):
                    add(i, j + 1, nk)
            if k == 0 and j - 1 >= jlo:
                for nk in range(K):
                    add(i, j - 1, nk)
        else:  # vertical stripes, neighboring blocks are horizontal
            if k == K - 1 and i + 1 <= ihi:
                for nk in range(K):
                    add(i + 1, j, nk)
            if k == 0 and i - 1 >= ilo:
                for nk in range(K):
                    add(i - 1, j, nk)
            # Vertical-block tiles span the full block height.
            add(i, j + 1, 0)
            add(i, j - 1, K - 1)

    return dx + dy

