def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper pattern."""
    # A unit square with i + j odd is bisected by a diagonal, so its
    # doubled black area is one.  If i + j is even, the square is all one
    # color.  Count line crossings from the black square containing
    # (0.5, 0.5) to determine that color.
    #
    # The resulting contribution is periodic with period four in both
    # coordinates.  Prefix sums over one 4 by 4 period make rectangle
    # queries constant time, including for negative coordinates.
    weights = [[0] * 4 for _ in range(4)]
    for j in range(4):
        for i in range(4):
            if (i + j) & 1:
                weights[j][i] = 1
            else:
                crossings = i + (j // 2) + ((i + j + 1) // 2)
                weights[j][i] = 2 if crossings % 2 == 0 else 0

    pref = [[0] * 5 for _ in range(5)]
    for j in range(4):
        for i in range(4):
            pref[j + 1][i + 1] = (
                weights[j][i] + pref[j][i + 1] + pref[j + 1][i] - pref[j][i]
            )
    period_total = pref[4][4]

    def cumulative(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        return (
            qx * qy * period_total
            + qx * pref[ry][4]
            + qy * pref[4][rx]
            + pref[ry][rx]
        )

    return (
        cumulative(C, D)
        - cumulative(A, D)
        - cumulative(C, B)
        + cumulative(A, B)
    )

