MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    if N < 1:
        return 0

    # For n=prod(p**e), the number of ordered M-tuples with product n is
    # prod(C(M+e-1,e)).  Both this weight and sigma(n) are multiplicative,
    # and sigma(n) == 0 mod 3 iff at least one prime-power factor has
    # sigma(p**e) == 0 mod 3.
    maxp = int(N ** 0.5) + 2
    sieve = bytearray(b"\x01") * (maxp + 1)
    if maxp >= 0:
        sieve[0] = 0
    if maxp >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, maxp + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= maxp:
                sieve[p * p:maxp + 1:p] = b"\x00" * (((maxp - p * p) // p) + 1)

    # Quotient values floor(N/i) are the only large arguments needed in the
    # prime-counting sieve and in the recursive summation.
    vals = []
    l = 1
    while l <= N:
        v = N // l
        vals.append(v)
        l = N // v + 1
    idx = {v: i for i, v in enumerate(vals)}

    # Count primes in each residue class modulo 3 for all quotient values.
    # Start with the corresponding counts of integers >=2, then remove
    # composites p*q with q prime and q>p, in increasing p order.
    g = []
    for r in range(3):
        g.append([sum(1 for k in range(2, min(v, 5) + 1) if k % 3 == r)
                  + (max(0, (v - r) // 3 - max(1, (2 - r + 2) // 3)) if v >= 6 else 0)
                  for v in vals])
    # The compact initializer above is easy to get wrong at small boundaries;
    # use direct residue counting formulas instead.
    for i, v in enumerate(vals):
        for r in range(3):
            if r == 0:
                g[r][i] = v // 3
            elif r == 1:
                g[r][i] = (v + 2) // 3
            else:
                g[r][i] = (v + 1) // 3
            if r == 1:
                g[r][i] -= 1  # remove integer 1

    for p in primes:
        if p * p > N:
            break
        # g at p-1 is the prime count before p; its argument is <= sqrt(N).
        # All needed arguments are represented by quotient values or are
        # obtained from a direct small sieve below.
        for i, v in enumerate(vals):
            if v < p * p:
                break
            qx = v // p
            # qx is a quotient value because v=floor(N/k).
            qi = idx[qx]
            # Count primes q>p in each residue, then remove p*q.
            # For qx small, p-1 is available through the small prefix table.
            for r in range(3):
                upto = g[r][qi]
                if p <= 3:
                    before = sum(1 for q in range(2, p) if q % 3 == r and sieve[q])
                else:
                    # p-1 is small (at most sqrt(N)); calculate via a
                    # prefix sieve of primes in the requested residue.
                    before = 0
                    for q in primes:
                        if q >= p:
                            break
                        if q % 3 == r:
                            before += 1
                target = (r * p) % 3
                g[target][i] -= upto - before

    # f(p) is M for p == 2 mod 3 and 0 otherwise.  Store the resulting
    # prime sums for queried arguments.
    prime_sum = [M * g[2][i] % MOD for i in range(len(vals))]

    def p2_count(x):
        if x < 2:
            return 0
        if x in idx:
            return g[2][idx[x]]
        # This path is only used for small x (sqrt of a recursive argument).
        return sum(1 for p in primes if p <= x and p % 3 == 2)

    def psum(x):
        if x < 2:
            return 0
        if x in idx:
            return prime_sum[idx[x]]
        return M * p2_count(x) % MOD

    # Prime-power local weights, indexed by exponent.
    maxe = N.bit_length()
    comb = [1] * (maxe + 1)
    for e in range(1, maxe + 1):
        comb[e] = comb[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    @lru_cache(None)
    def rough(x, start):
        # Sum of weights of integers <=x whose prime factors are all at
        # least primes[start].  Choose the least prime and its exponent.
        if x < 2:
            return 1
        root = int(x ** 0.5)
        ans = 1
        lower = primes[start - 1] if start > 0 else 1
        # Prime factors greater than sqrt(x) can only occur to exponent 1.
        ans += psum(x) - psum(max(root, lower))
        ans %= MOD
        for j in range(start, len(primes)):
            p = primes[j]
            if p > root:
                break
            # Sum over exponent of the least prime p.
            power = p
            e = 1
            while power <= x:
                if (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2):
                    ans += comb[e] * rough(x // power, j + 1)
                    ans %= MOD
                power *= p
                e += 1
        return ans

    return rough(N, 0)

