    good when its two prefix states are equal. If a path visits a quotient state c times,
    it contributes c*(c-1)/2 good substrings. The DP tracks visit counts for all four states
    and the current state. Its number of states is O(n^3), suitable for n <= 50.

    Return the count modulo 998244353.
    """
    mod = 998244353

    # In the quotient, C = A xor B, so the three character transitions are 1, 2, 3.
    transitions = {"A": (1,), "B": (2,), "C": (3,), "?": (1, 2, 3)}
    # State key: (visits to states 0,1,2,3, current quotient state).
    dp = {(1, 0, 0, 0, 0): 1}
    for ch in s:
        ndp = {}
        for (v0, v1, v2, v3, state), ways in dp.items():
            for delta in transitions[ch]:
                nxt = state ^ delta
                if nxt == 0:
                    key = (v0 + 1, v1, v2, v3, nxt)
                elif nxt == 1:
                    key = (v0, v1 + 1, v2, v3, nxt)
                elif nxt == 2:
                    key = (v0, v1, v2 + 1, v3, nxt)
                else:
                    key = (v0, v1, v2, v3 + 1, nxt)
                ndp[key] = (ndp.get(key, 0) + ways) % mod
        dp = ndp

    answer = 0
    for (v0, v1, v2, v3, _state), ways in dp.items():
        good = (v0 * (v0 - 1) + v1 * (v1 - 1)
                + v2 * (v2 - 1) + v3 * (v3 - 1)) // 2
