n = len(s)
values = [ord(ch) - ord("a") for ch in s]
bit = [1 << c for c in values]

next_boundary = [n] * n
counts = [0] * 26
distinct = 0
right = 0
for left in range(n):
    while right < n:
        c = values[right]
        if counts[c] == 0 and distinct == k:
            break
        if counts[c] == 0:
            distinct += 1
        counts[c] += 1
        right += 1
    next_boundary[left] = right
    c = values[left]
    counts[c] -= 1
    if counts[c] == 0:
        distinct -= 1

suffix_parts = [0] * (n + 1)
for i in range(n - 1, -1, -1):
    suffix_parts[i] = 1 + suffix_parts[next_boundary[i]]
best = suffix_parts[0]

sparse = [bit]
level = 1
while (1 << level) <= n:
    previous = sparse[-1]
    half = 1 << (level - 1)
    sparse.append([
        previous[i] | previous[i + half]
        for i in range(n - (1 << level) + 1)
    ])
    level += 1

prefix = [[0] * (n + 1) for _ in range(26)]
for c in range(26):
    row = prefix[c]
    total = 0
    for i, value in enumerate(values, 1):
        if value == c:
            total += 1
        row[i] = total

def range_mask(left: int, right: int) -> int:
    length = right - left
    level = length.bit_length() - 1
    width = 1 << level
    return sparse[level][left] | sparse[level][right - width]

start = 0
partitions_before = 0
while start < n:
    end = next_boundary[start]
    for position in range(start, end):
        old = values[position]
        for new in range(26):
            if new == old:
                continue
            new_bit = 1 << new
            low = position
            high = n
            while low < high:
                middle = (low + high) // 2
                mask = range_mask(start, middle + 1)
                distinct_after = mask.bit_count()
                if prefix[old][middle + 1] - prefix[old][start] == 1:
                    distinct_after -= 1
                if not (mask & new_bit):
                    distinct_after += 1
                if distinct_after > k:
                    high = middle
                else:
                    low = middle + 1

            if low == position:
                # The edit itself is the first character excluded from this
                # partition, so it starts the next partition.
                next_low = position
                next_high = n
                while next_low < next_high:
                    middle = (next_low + next_high) // 2
                    mask = range_mask(position, middle + 1)
                    distinct_after = mask.bit_count()
                    if prefix[old][middle + 1] - prefix[old][position] == 1:
                        distinct_after -= 1
                    if not (mask & new_bit):
                        distinct_after += 1
                    if distinct_after > k:
                        next_high = middle
                    else:
                        next_low = middle + 1
                candidate = partitions_before + 2 + suffix_parts[next_low]
            else:
                candidate = partitions_before + 1 + suffix_parts[low]
            if candidate > best:
                best = candidate
    partitions_before += 1
    start = end

return best

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    if n != len(tiles) or h <= 0 or w <= 0:
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]
    shapes = [tuple({(a, b), (b, a)}) for a, b in tiles]

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True

        empty = full ^ occupied
        needed = empty.bit_count()
        sums = {0}
        for i, area in enumerate(areas):
            if available & (1 << i):
                sums |= {s + area for s in tuple(sums) if s + area <= needed}
        if needed not in sums:
            return False

        first = (empty & -empty).bit_length() - 1
        row, col = divmod(first, w)

        for i in range(n):
            bit = 1 << i
            if not (available & bit):
                continue
            for height, width in shapes[i]:
                if row + height > h or col + width > w:
                    continue
                placement = 0
                for rr in range(row, row + height):
                    for cc in range(col, col + width):
                        placement |= 1 << (rr * w + cc)
                if occupied & placement == 0 and search(occupied | placement, available ^ bit):
                    return True
        return False

    available = sum(1 << i for i, area in enumerate(areas) if area <= h * w)
    return search(0, available)

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    import heapq

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y - sj * K if (si - sj) % 2 == 0 else S_x - si * K
    tk = T_y - tj * K if (ti - tj) % 2 == 0 else T_x - ti * K
    macro = abs(si - ti) + abs(sj - tj)
    if macro > 80:
        return macro
    if (si, sj) == (ti, tj):
        return abs(sk - tk)

    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    strips = sorted({0, K - 1, sk, tk})
    cells = [(i, j) for i in range(lo_i, hi_i + 1)
             for j in range(lo_j, hi_j + 1)]
    nodes = {}
    for i, j in cells:
        for q in strips:
            nodes[i, j, q] = len(nodes)
    graph = [[] for _ in nodes]
    for i, j in cells:
        same = (i - j) % 2 == 0
        for a in strips:
            u = nodes[i, j, a]
            for b in strips:
                v = nodes[i, j, b]
                if u != v:
                    graph[u].append((v, abs(a - b)))
        if i < hi_i:
            if same:  # H left, V right: V strip 0 touches its left edge.
                pairs = [(a, 0) for a in strips]
            else:     # V left, H right: V strip K-1 touches its right edge.
                pairs = [(K - 1, b) for b in strips]
            for a, b in pairs:
                u, v = nodes[i, j, a], nodes[i + 1, j, b]
                graph[u].append((v, 1))
                graph[v].append((u, 1))
        if j < hi_j:
            if same:  # H below, V above: H strip K-1 touches its top edge.
                pairs = [(K - 1, b) for b in strips]
            else:     # V below, H above: H strip 0 touches its bottom edge.
                pairs = [(a, 0) for a in strips]
            for a, b in pairs:
                u, v = nodes[i, j, a], nodes[i, j + 1, b]
                graph[u].append((v, 1))
                graph[v].append((u, 1))

    start, goal = nodes[si, sj, sk], nodes[ti, tj, tk]
    dist = [10**100] * len(nodes)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return macro

