from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the graph distance between the tiles containing the two points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def stripe(i, j, x, y):
        return (y - j * K) if (i - j) % 2 == 0 else (x - i * K)

    sk, tk = stripe(si, sj, S_x, S_y), stripe(ti, tj, T_x, T_y)
    if (si, sj, sk) == (ti, tj, tk):
        return 0
    dx, dy = abs(ti - si), abs(tj - sj)
    if max(dx, dy) > 30 or K > 200:
        return dx + dy

    margin = min(K + 2, 50)
    ilo, ihi = min(si, ti) - margin, max(si, ti) + margin
    jlo, jhi = min(sj, tj) - margin, max(sj, tj) + margin
    start, target = (si, sj, sk), (ti, tj, tk)
    q = deque([start])
    dist = {start: 0}

    while q:
        i, j, k = q.popleft()
        d = dist[(i, j, k)]
        if (i, j, k) == target:
            return d
        same = (i - j) % 2 == 0

        def add(ni, nj, nk):
            if ilo <= ni <= ihi and jlo <= nj <= jhi:
                state = (ni, nj, nk)
                if state not in dist:
                    dist[state] = d + 1
                    q.append(state)

        if k > 0:
            add(i, j, k - 1)
        if k + 1 < K:
            add(i, j, k + 1)
        if same:
            add(i + 1, j, 0)
            add(i - 1, j, K - 1)
            if k == K - 1:
                for nk in range(K):
                    add(i, j + 1, nk)
            if k == 0:
                for nk in range(K):
                    add(i, j - 1, nk)
        else:
            if k == K - 1:
                for nk in range(K):
                    add(i + 1, j, nk)
            if k == 0:
                for nk in range(K):
                    add(i - 1, j, nk)
            add(i, j + 1, 0)
            add(i, j - 1, K - 1)

    return dx + dy

