def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count the permutations specified by the function contract."""
    if A < 2 or B < 2:
        return 0

    shape = [A] * (B - 1) + [A - 1]
    size = A * B - 1

    def successors(state):
        for row, limit in enumerate(shape):
            col = state[row]
            if col >= limit:
                continue
            if row and col >= state[row - 1]:
                continue
            # A value can be row-inserted to the southeast missing cell when
            # each row's last-column entry is preceded by the next row's
            # penultimate-column entry.
            if col == A - 1 and row + 1 < B and state[row + 1] < A - 1:
                continue
            yield state[:row] + (col + 1,) + state[row + 1:]

    zero = (0,) * B
    full = tuple(shape)
    states = [zero]
    index = {zero: 0}
    for state in states:
        for nxt in successors(state):
            if nxt not in index:
                index[nxt] = len(states)
                states.append(nxt)

    ways = [0] * len(states)
    ways[0] = 1
    for i, state in enumerate(states):
        if ways[i]:
            for nxt in successors(state):
                ways[index[nxt]] = (ways[index[nxt]] + ways[i]) % M

    eligible = ways[index[full]]
    factorial = 1
    for k in range(2, size + 1):
        factorial = factorial * k % M
    hooks = 1
    for row, width in enumerate(shape):
        for col in range(width):
            below = sum(1 for later in shape[row + 1:] if later > col)
            hooks = hooks * (width - col + below) % M
    tableaux = factorial * pow(hooks, M - 2, M) % M
    return tableaux * eligible % M

